package org.springframework.samples.petclinic.rest.advice;

/**
 * Thrown when a request to create an owner supplies a telephone whose normalized form is already
 * used by another owner. Telephone numbers must be unique across owners, so the
 * {@link ExceptionControllerAdvice} reports this back to the client as a 409 Conflict.
 */
public class DuplicateOwnerTelephoneException extends RuntimeException {

    private final String telephone;

    public DuplicateOwnerTelephoneException(String telephone) {
        super("Telephone already in use: " + telephone);
        this.telephone = telephone;
    }

    public String getTelephone() {
        return this.telephone;
    }

}

