17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.regex.Pattern;
24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
29	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
30	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
31	import org.springframework.samples.petclinic.mapper.OwnerMapper;
32	import org.springframework.samples.petclinic.mapper.PetMapper;
33	import org.springframework.samples.petclinic.mapper.VisitMapper;
34	import org.springframework.samples.petclinic.model.Owner;
35	import org.springframework.samples.petclinic.model.Pet;
36	import org.springframework.samples.petclinic.model.Visit;
37	import org.springframework.samples.petclinic.rest.api.OwnersApi;
38	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
39	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.PetDto;
41	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.util.StringUtils;
47	import org.springframework.web.bind.annotation.CrossOrigin;
48	import org.springframework.web.bind.annotation.RequestMapping;
49	import org.springframework.web.bind.annotation.RestController;
50	import org.springframework.web.util.UriComponentsBuilder;
51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /**
64	     * Basic syntactic check for an email address: a non-empty local part, an '@', and a domain with
65	     * at least one dot and a two-or-more letter top-level label. Case is ignored here; accepted
66	     * addresses are lower-cased before being stored.
67	     */
68	    private static final Pattern EMAIL_PATTERN =
69	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
70	
71	    private final ClinicService clinicService;
72	
73	    private final OwnerMapper ownerMapper;
74	
75	    private final PetMapper petMapper;
76	
77	    private final VisitMapper visitMapper;
78	
79	    public OwnerRestControllerV1(ClinicService clinicService,
80	                                 OwnerMapper ownerMapper,
81	                                 PetMapper petMapper,
82	                                 VisitMapper visitMapper) {
83	        this.clinicService = clinicService;
84	        this.ownerMapper = ownerMapper;
85	        this.petMapper = petMapper;
86	        this.visitMapper = visitMapper;
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
92	        Collection<Owner> owners;
93	        if (lastName != null) {
94	            owners = this.clinicService.findOwnerByLastName(lastName);
95	        } else {
96	            owners = this.clinicService.findAllOwners();
97	        }
98	        if (owners.isEmpty()) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
107	        Owner owner = this.clinicService.findOwnerById(ownerId);
108	        if (owner == null) {
109	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
110	        }
111	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
117	        validateRequiredFields(ownerFieldsDto);
118	        HttpHeaders headers = new HttpHeaders();
119	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
120	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
121	        owner.setEmail(normalizeEmail(owner.getEmail()));
122	        if (owner.getRegistrationDate() == null) {
123	            owner.setRegistrationDate(LocalDate.now());
124	        }
125	        if (!this.clinicService.findOwnerByTelephone(owner.getTelephone()).isEmpty()) {
126	            throw new DuplicateOwnerTelephoneException(owner.getTelephone());
127	        }
128	        owner.setCustomerCode(buildCustomerCode(owner.getLastName()));
129	        this.clinicService.saveOwner(owner);
130	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
131	        headers.setLocation(UriComponentsBuilder.newInstance()
132	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
133	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
134	    }
135	
136	    /**
137	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
138	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
139	     * so the client receives a 400 whose {@code errors} array lists each missing field.
140	     *
141	     * @param ownerFieldsDto the submitted owner fields
142	     */
143	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
144	        List<String> missingFields = new ArrayList<>();
145	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
146	            missingFields.add("firstName");
147	        }
148	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
149	            missingFields.add("lastName");
150	        }
151	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
152	            missingFields.add("address");
153	        }
154	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
155	            missingFields.add("city");
156	        }
157	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
158	            missingFields.add("telephone");
159	        }
160	        if (!missingFields.isEmpty()) {
161	            throw new MissingOwnerFieldsException(missingFields);
162	        }
163	    }
164	
165	    /**
166	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
167	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
168	     * address; the accepted value is lower-cased before it is stored and returned.
169	     *
170	     * @param email the raw email value submitted by the client, or {@code null}
171	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
172	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
173	     */
174	    private String normalizeEmail(String email) {
175	        if (!StringUtils.hasText(email)) {
176	            return email;
177	        }
178	        if (!EMAIL_PATTERN.matcher(email).matches()) {
179	            throw new InvalidOwnerFieldsException(List.of("email"));
180	        }
181	        return email.toLowerCase();
182	    }
183	
184	    /**
185	     * Builds the owner's customer code formatted {@code <LAST3>-<NNNN>}, where LAST3 is the
186	     * upper-cased first three letters of the last name and NNNN is a global 4-digit zero-padded
187	     * sequence equal to one more than the current number of owners (e.g. {@code SMI-0007}).
